// Replays the replication conformance vectors (vectors/replication/*.trace,
// generated by orderer-rust's simulator) against this implementation of the
// protocol core. Every effect and state line must match exactly.
//
//   replication_test <vectors-dir>
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <sstream>

#include "check.hpp"
#include "orderer/consensus.hpp"

using namespace orderer::consensus;
namespace fs = std::filesystem;

namespace {

std::string hexs(const std::vector<std::uint8_t>& d) {
    if (d.empty()) return "-";
    static const char* h = "0123456789abcdef";
    std::string s;
    for (auto b : d) { s += h[b >> 4]; s += h[b & 15]; }
    return s;
}

std::vector<std::uint8_t> unhex(const std::string& s) {
    std::vector<std::uint8_t> v;
    if (s == "-") return v;
    for (std::size_t i = 0; i + 1 < s.size(); i += 2) v.push_back(static_cast<std::uint8_t>(std::stoi(s.substr(i, 2), nullptr, 16)));
    return v;
}

std::string fmt_entry(const Entry& e) { return std::to_string(e.term) + ":" + hexs(e.data); }

std::string fmt_entries(const std::vector<Entry>& es) {
    if (es.empty()) return "-";
    std::string s;
    for (std::size_t i = 0; i < es.size(); ++i) { if (i) s += ","; s += fmt_entry(es[i]); }
    return s;
}

std::vector<Entry> parse_entries(const std::string& s) {
    std::vector<Entry> v;
    if (s == "-") return v;
    std::stringstream ss(s);
    std::string part;
    while (std::getline(ss, part, ',')) {
        auto c = part.find(':');
        v.push_back(Entry{static_cast<Term>(std::stoul(part.substr(0, c))), unhex(part.substr(c + 1))});
    }
    return v;
}

std::string fmt_msg(const Msg& m) {
    std::ostringstream o;
    switch (m.kind) {
        case Msg::Kind::Vote: o << "vote " << m.term << " " << m.last_index << " " << m.last_term << " " << int(m.pre); break;
        case Msg::Kind::VoteReply: o << "votereply " << m.term << " " << int(m.granted) << " " << int(m.pre); break;
        case Msg::Kind::Append:
            o << "append " << m.term << " " << m.prev_index << " " << m.prev_term << " " << m.commit << " " << fmt_entries(m.entries);
            break;
        case Msg::Kind::AppendReply: o << "appendreply " << m.term << " " << int(m.success) << " " << m.index; break;
    }
    return o.str();
}

Msg parse_msg(const std::vector<std::string>& w, std::size_t at) {
    auto n = [&](std::size_t i) { return std::stoull(w.at(at + i)); };
    const std::string& k = w.at(at);
    if (k == "vote") return Msg::vote(static_cast<Term>(n(1)), n(2), static_cast<Term>(n(3)), n(4) == 1);
    if (k == "votereply") return Msg::vote_reply(static_cast<Term>(n(1)), n(2) == 1, n(3) == 1);
    if (k == "append") return Msg::append(static_cast<Term>(n(1)), n(2), static_cast<Term>(n(3)), parse_entries(w.at(at + 5)), n(4));
    if (k == "appendreply") return Msg::append_reply(static_cast<Term>(n(1)), n(2) == 1, n(3));
    throw std::runtime_error("unknown message " + k);
}

std::string fmt_effect(const Effect& e) {
    std::ostringstream o;
    switch (e.kind) {
        case Effect::Kind::Send: o << "send " << int(e.to) << " " << fmt_msg(e.msg); break;
        case Effect::Kind::Persist: {
            const auto& p = e.persist;
            o << "persist " << p.token << " " << p.term << " ";
            if (p.voted_for) o << int(*p.voted_for); else o << "-";
            o << " " << p.from << " ";
            if (p.compact) o << p.compact->first << ":" << p.compact->second; else o << "-";
            o << " " << fmt_entries(p.entries);
            break;
        }
        case Effect::Kind::Apply: o << "apply " << e.index << " " << fmt_entry(e.entry); break;
        case Effect::Kind::NeedSnapshot: o << "needsnap " << int(e.to) << " " << e.index << " " << e.term; break;
        case Effect::Kind::Restore: o << "restore " << e.index << " " << e.term; break;
    }
    return o.str();
}

std::string fmt_state(const Node& n) {
    std::ostringstream o;
    o << "state role=" << role_name(n.role()) << " term=" << n.term() << " leader=";
    if (n.leader()) o << int(*n.leader()); else o << "-";
    o << " commit=" << n.commit_index() << " applied=" << n.applied_index() << " base=" << n.base() << " last=" << n.last_index();
    return o.str();
}

std::vector<std::string> words(const std::string& line) {
    std::vector<std::string> w;
    std::istringstream is(line);
    std::string t;
    while (is >> t) w.push_back(t);
    return w;
}

std::string field(const std::string& line, const std::string& key) {
    for (const auto& w : words(line)) if (w.rfind(key + "=", 0) == 0) return w.substr(key.size() + 1);
    throw std::runtime_error("missing " + key);
}

std::unique_ptr<Node> parse_node(const std::string& line) {
    std::vector<NodeId> peers;
    { std::stringstream ss(field(line, "peers")); std::string p; while (std::getline(ss, p, ',')) peers.push_back(static_cast<NodeId>(std::stoi(p))); }
    Config cfg;
    cfg.election_ticks = static_cast<std::uint32_t>(std::stoul(field(line, "election")));
    cfg.heartbeat_ticks = static_cast<std::uint32_t>(std::stoul(field(line, "heartbeat")));
    cfg.max_batch = std::stoul(field(line, "batch"));
    cfg.pre_vote = field(line, "prevote") == "1";
    // disk=term:voted:base:base_term:entries
    const std::string d = field(line, "disk");
    std::vector<std::string> f;
    { std::size_t at = 0; for (int i = 0; i < 4; ++i) { auto c = d.find(':', at); f.push_back(d.substr(at, c - at)); at = c + 1; } f.push_back(d.substr(at)); }
    Disk disk;
    disk.term = static_cast<Term>(std::stoul(f[0]));
    if (f[1] != "-") disk.voted_for = static_cast<NodeId>(std::stoi(f[1]));
    disk.base = std::stoull(f[2]);
    disk.base_term = static_cast<Term>(std::stoul(f[3]));
    disk.log = parse_entries(f[4]);
    return std::make_unique<Node>(static_cast<NodeId>(std::stoi(field(line, "id"))), peers, cfg, std::stoull(field(line, "seed")), std::move(disk));
}

// Returns the number of checked drain points, or throws with the first difference.
std::size_t replay(const std::string& text) {
    std::unique_ptr<Node> node;
    std::vector<std::string> expected;
    std::size_t checked = 0, ln = 0;
    std::istringstream in(text);
    std::string line;
    auto fail = [&](const std::string& m) { throw std::runtime_error("line " + std::to_string(ln) + ": " + m); };
    while (std::getline(in, line)) {
        ++ln;
        auto w = words(line);
        if (w.empty()) continue;
        if (w[0] == "node") { node = parse_node(line); }
        else if (w[0] == "in") {
            if (!node) fail("input before node");
            const std::string& op = w.at(1);
            if (op == "tick") node->tick();
            else if (op == "step") node->step(static_cast<NodeId>(std::stoi(w.at(2))), parse_msg(w, 3));
            else if (op == "propose") (void)node->propose(unhex(w.at(2)));
            else if (op == "replicate") node->replicate();
            else if (op == "persisted") node->persisted(std::stoull(w.at(2)));
            else if (op == "compact") node->compact(std::stoull(w.at(2)));
            else if (op == "install") node->install_snapshot(static_cast<NodeId>(std::stoi(w.at(2))), static_cast<Term>(std::stoul(w.at(3))), std::stoull(w.at(4)), static_cast<Term>(std::stoul(w.at(5))));
            else fail("unknown input " + op);
        } else if (w[0] == "out" || w[0] == "state") {
            expected.push_back(line);
            if (w[0] == "state") {
                if (!node) fail("state before node");
                std::vector<std::string> got;
                for (const auto& e : node->take_effects()) got.push_back("out " + fmt_effect(e));
                got.push_back(fmt_state(*node));
                if (got != expected) {
                    std::size_t i = 0;
                    while (i < got.size() && i < expected.size() && got[i] == expected[i]) ++i;
                    fail("output differs at item " + std::to_string(i) + "\n  want: " + (i < expected.size() ? expected[i] : "<end>") +
                         "\n  got:  " + (i < got.size() ? got[i] : "<end>"));
                }
                ++checked;
                expected.clear();
            }
        } else if (w[0] != "#") {
            fail("unknown line kind " + w[0]);
        }
    }
    return checked;
}

fs::path VEC;

}  // namespace

TEST(replication_conformance_vectors) {
    std::vector<fs::path> files;
    for (auto& e : fs::directory_iterator(VEC / "replication"))
        if (e.path().extension() == ".trace") files.push_back(e.path());
    std::sort(files.begin(), files.end());
    CHECK(!files.empty()) << "no traces in " << (VEC / "replication");
    std::size_t total = 0;
    for (const auto& f : files) {
        std::ifstream is(f);
        std::stringstream ss;
        ss << is.rdbuf();
        try {
            std::size_t n = replay(ss.str());
            CHECK(n > 100) << f << ": only " << n << " checked steps";
            total += n;
        } catch (const std::exception& e) {
            CHECK(false) << f.filename() << ": " << e.what();
        }
    }
    std::cout << "  replayed " << files.size() << " traces, " << total << " drain points\n";
}

int main(int argc, char** argv) {
    VEC = argc > 1 ? argv[1] : "vectors";
    return check::run_all();
}
